{
  "findings": [
    {
      "check_id": "CKV_GCP_29",
      "title": "Cloud SQL instance allows connections from the entire internet (0.0.0.0/0)",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The authorized_networks block includes '0.0.0.0/0', which exposes the database to the public internet, significantly increasing the attack surface."
    },
    {
      "check_id": "CKV_GCP_30",
      "title": "Cloud SQL instance does not enforce SSL/TLS for connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "require_ssl is set to false, allowing unencrypted data transmission between clients and the database, risking data interception."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Cloud SQL instance has deletion protection disabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "deletion_protection is set to false, meaning the database can be accidentally deleted via Terraform destroy or console actions without safeguards."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Removed the '0.0.0.0/0' authorized network entry to restrict access to internal networks only. Enabled SSL enforcement by setting require_ssl to true. Enabled deletion protection to prevent accidental destruction of the database instance."
}
